<script setup lang="ts">import {computed,ref} from "vue";import {Download} from "lucide-vue-next";import AppShell from "@/components/zs/AppShell.vue";import PageHeader from "@/components/zs/PageHeader.vue";import Panel from "@/components/zs/Panel.vue";import StatCard from "@/components/zs/StatCard.vue";import Tabs from "@/components/zs/Tabs.vue";import ZButton from "@/components/zs/ZButton.vue";import DataTable,{type Column} from "@/components/zs/DataTable.vue";import AreaChart from "@/components/zs/AreaChart.vue";import {formatMoney,toMinor} from "@/lib/money";import {showToast} from "@/composables/useToast";import {setPageMeta} from "@/lib/page-meta";setPageMeta("Financial Reports","Trial balance, profitability, financial position and cash flow for the active company.");const tab=ref("Profit & Loss"),period=ref("Year to date"),comparison=ref("Prior period");const reports:any={"Profit & Loss":[["Revenue",toMinor(63940000)],["Cost of goods sold",toMinor(-5182000)],["Gross profit",toMinor(58758000)],["Operating expenses",toMinor(-37530400)],["Net profit",toMinor(21227600)]],"Balance Sheet":[["Current assets",toMinor(47066600)],["Non-current assets",toMinor(5120000)],["Total assets",toMinor(52186600)],["Liabilities",toMinor(19139300)],["Equity",toMinor(33047300)]],"Trial Balance":[["Assets",toMinor(52186600)],["Liabilities",toMinor(-19139300)],["Equity",toMinor(-33047300)],["Debits",toMinor(84217500)],["Credits",toMinor(-84217500)]],"Cash Flow":[["Operating activities",toMinor(14680000)],["Investing activities",toMinor(-3920000)],["Financing activities",toMinor(-2500000)],["Net movement",toMinor(8260000)],["Closing cash",toMinor(31440800)]]};const rows=computed(()=>reports[tab.value].map((x:any,i:number)=>({id:String(i),label:x[0],amount:x[1],previous:Math.round(x[1]*.91),variance:x[1]-Math.round(x[1]*.91)})));const columns:Column[]=[{key:"label",header:"Line item"},{key:"previous",header:"Comparison",align:"right",class:"num"},{key:"amount",header:"Current",align:"right",class:"num"},{key:"variance",header:"Variance",align:"right",class:"num"}];const trend=[{month:"Apr",actual:6.1,comparison:5.5},{month:"May",actual:5.8,comparison:5.2},{month:"Jun",actual:7.4,comparison:6.7},{month:"Jul",actual:8.9,comparison:7.8},{month:"Aug",actual:8.4,comparison:7.5},{month:"Sep",actual:9.6,comparison:8.2}];</script><template><AppShell><PageHeader title="Financial Reports" description="Backend-authoritative statements with comparison and drill-through ready views"><template #actions><ZButton variant="outline" @click="showToast('Export queued','The real API will generate the final PDF or spreadsheet.','info')"><Download class="size-4"/>Export</ZButton></template></PageHeader><div class="mb-4 grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><StatCard label="Revenue YTD" :value="formatMoney(toMinor(63940000))" tone="brand"/><StatCard label="Net profit" :value="formatMoney(toMinor(21227600))" tone="success"/><StatCard label="Total assets" :value="formatMoney(toMinor(52186600))"/><StatCard label="Closing cash" :value="formatMoney(toMinor(31440800))" tone="warning"/></div><Panel><Tabs v-model="tab" :items="['Profit & Loss','Balance Sheet','Trial Balance','Cash Flow']"/><div class="flex flex-wrap gap-2 border-b border-line p-3"><select v-model="period" class="field w-44"><option>Year to date</option><option>This quarter</option><option>This month</option></select><select v-model="comparison" class="field w-44"><option>Prior period</option><option>Prior year</option><option>No comparison</option></select></div><div class="grid xl:grid-cols-[1fr_22rem]"><DataTable :columns="columns" :rows="rows" :min-width="680"><template #label="{row}:{row:any}"><span class="font-medium text-content">{{row.label}}</span></template><template #previous="{row}:{row:any}">{{formatMoney(row.previous)}}</template><template #amount="{row}:{row:any}">{{formatMoney(row.amount)}}</template><template #variance="{row}:{row:any}"><span :class="row.variance>=0?'text-success':'text-danger'">{{formatMoney(row.variance)}}</span></template></DataTable><div class="border-l border-line p-4"><p class="label-caps">Six-month trend</p><AreaChart class="mt-4" :data="trend" x-key="month" :series="[{key:'actual',color:'var(--chart-1)',id:'report-actual'},{key:'comparison',color:'var(--chart-2)',id:'report-compare'}]" :height="230"/></div></div></Panel></AppShell></template>